 public async Task<JsonResponseRequest<FlotaResultadoDto>> CorregirOperacionDiaAsync(int u,FlotaOperacionDiaCorregirDto x,CancellationToken ct){if(x.IdOperacionDia<=0)return R(new FlotaResultadoDto(),false,"Selecciona una operacion valida.");x.FlgTrabajo=(x.FlgTrabajo??"").Trim().ToUpperInvariant();x.FlgCobrable=(x.FlgCobrable??"").Trim().ToUpperInvariant();if(x.FlgTrabajo!="S"&&x.FlgTrabajo!="N")return R(new FlotaResultadoDto(),false,"FlgTrabajo invalido. Usa S o N.");if(x.FlgCobrable!="S"&&x.FlgCobrable!="N")return R(new FlotaResultadoDto(),false,"FlgCobrable invalido. Usa S o N.");if(string.IsNullOrWhiteSpace(x.CodMotivo))return R(new FlotaResultadoDto(),false,"Selecciona el motivo del dia.");if(string.IsNullOrWhiteSpace(x.Motivo))return R(new FlotaResultadoDto(),false,"Ingresa el motivo.");if(x.KmInicial.HasValue&&x.KmInicial.Value<0||x.KmFinal.HasValue&&x.KmFinal.Value<0)return R(new FlotaResultadoDto(),false,"Kilometraje invalido.");if(x.KmInicial.HasValue&&x.KmFinal.HasValue&&x.KmFinal.Value<x.KmInicial.Value)return R(new FlotaResultadoDto(),false,"El km final no puede ser menor que el km inicial.");if(x.FechaHoraInicio.HasValue&&x.FechaHoraFin.HasValue&&x.FechaHoraFin.Value<x.FechaHoraInicio.Value)return R(new FlotaResultadoDto(),false,"La hora final no puede ser menor que la hora inicial.");var d=await _repo.CorregirOperacionDiaAsync(Empresa,Est,u,x,ct);return R(d,d.Ok,d.Mensaje);}
