 public async Task<JsonResponseRequest<FlotaResultadoDto>> GuardarOperacionMobileAsync(int u,FlotaOperacionMobileGuardarDto x,CancellationToken ct){if(x.IdContrato<=0)return R(new FlotaResultadoDto(),false,"Selecciona un contrato valido.");x.FlgTrabajo=(x.FlgTrabajo??"").Trim().ToUpperInvariant();x.FlgCobrable=(x.FlgCobrable??"").Trim().ToUpperInvariant();x.FlgPagoCombustible=string.IsNullOrWhiteSpace(x.FlgPagoCombustible)?null:x.FlgPagoCombustible.Trim().ToUpperInvariant();x.ModoRegistro=string.IsNullOrWhiteSpace(x.ModoRegistro)?null:x.ModoRegistro.Trim().ToUpperInvariant();if(x.FlgTrabajo!="S"&&x.FlgTrabajo!="N")return R(new FlotaResultadoDto(),false,"FlgTrabajo invalido. Usa S o N.");if(x.FlgCobrable!="S"&&x.FlgCobrable!="N")return R(new FlotaResultadoDto(),false,"FlgCobrable invalido. Usa S o N.");if(string.IsNullOrWhiteSpace(x.CodMotivo))return R(new FlotaResultadoDto(),false,"Selecciona el motivo del dia.");if(x.KmInicial.HasValue&&x.KmInicial.Value<0||x.KmFinal.HasValue&&x.KmFinal.Value<0)return R(new FlotaResultadoDto(),false,"Kilometraje invalido.");if(x.KmInicial.HasValue&&x.KmFinal.HasValue&&x.KmFinal.Value<x.KmInicial.Value)return R(new FlotaResultadoDto(),false,"El km final no puede ser menor que el km inicial.");if(x.FechaHoraInicio.HasValue&&x.FechaHoraFin.HasValue&&x.FechaHoraFin.Value<x.FechaHoraInicio.Value)return R(new FlotaResultadoDto(),false,"La hora final no puede ser menor que la hora inicial.");if(x.GalonesCargados<0)return R(new FlotaResultadoDto(),false,"GalonesCargados invalido.");if(x.ImporteCombustible<0)return R(new FlotaResultadoDto(),false,"ImporteCombustible invalido.");var d=await _repo.GuardarOperacionMobileAsync(Empresa,Est,u,x,ct);return R(d,d.Ok,d.Mensaje);}
 public async Task<JsonResponseRequest<FlotaResultadoDto>> RegistrarCombustibleOperacionAsync(int u,FlotaCombustibleRegistrarDto x,CancellationToken ct){if(x.IdContrato<=0||x.IdChofer<=0||x.IdVehiculo<=0)return R(new FlotaResultadoDto(),false,"Completa contrato, chofer y vehiculo.");if(x.IdOperacionDia.HasValue&&x.IdOperacionDia.Value<=0)return R(new FlotaResultadoDto(),false,"IdOperacionDia invalido.");x.FlgPagoCombustible=string.IsNullOrWhiteSpace(x.FlgPagoCombustible)?null:x.FlgPagoCombustible.Trim().ToUpperInvariant();if(x.Galones<=0)return R(new FlotaResultadoDto(),false,"Galones debe ser mayor que cero.");if(x.Importe<0)return R(new FlotaResultadoDto(),false,"Importe invalido.");if(x.FlgPagoCombustible!=null&&x.FlgPagoCombustible!="C"&&x.FlgPagoCombustible!="D"&&x.FlgPagoCombustible!="P")return R(new FlotaResultadoDto(),false,"FlgPagoCombustible invalido. Usa C, D o P.");var d=await _repo.RegistrarCombustibleOperacionAsync(Empresa,Est,u,x,ct);return R(d,d.Ok,d.Mensaje);}
