 public async Task<JsonResponseRequest<List<FlotaPagoContratoListItemDto>>> ListarPagosContratoPendientesAsync(int? idContrato,DateTime? fechaDesde,DateTime? fechaHasta,string? texto,CancellationToken ct){if(idContrato.HasValue&&idContrato.Value<=0)return R(new List<FlotaPagoContratoListItemDto>(),false,"Selecciona un contrato valido.");if(fechaDesde.HasValue&&fechaHasta.HasValue&&fechaHasta.Value.Date<fechaDesde.Value.Date)return R(new List<FlotaPagoContratoListItemDto>(),false,"Rango de fechas invalido.");texto=string.IsNullOrWhiteSpace(texto)?null:texto.Trim();if(texto!=null&&texto.Length>100)texto=texto[..100];return R(await _repo.ListarPagosContratoPendientesAsync(Empresa,Est,idContrato,fechaDesde,fechaHasta,texto,ct));}
