 public async Task<JsonResponseRequest<FlotaResultadoDto>> RegistrarAdjuntoFlotaAsync(int u,FlotaAdjuntoRegistrarDto x,CancellationToken ct){x.TipoEntidad=(x.TipoEntidad??"").Trim().ToUpperInvariant();x.TipoAdjunto=(x.TipoAdjunto??"").Trim().ToUpperInvariant();if(x.IdEntidad<=0)return R(new FlotaResultadoDto(),false,"Selecciona una entidad valida.");if(x.TipoEntidad!="OPERACION_DIA"&&x.TipoEntidad!="PAGO_CONTRATO"&&x.TipoEntidad!="RECIBO"&&x.TipoEntidad!="COMBUSTIBLE")return R(new FlotaResultadoDto(),false,"TipoEntidad invalido.");if(x.TipoAdjunto!="RECIBO_GLP"&&x.TipoAdjunto!="VOUCHER_PAGO"&&x.TipoAdjunto!="OTRO")return R(new FlotaResultadoDto(),false,"TipoAdjunto invalido.");if(string.IsNullOrWhiteSpace(x.RutaArchivo))return R(new FlotaResultadoDto(),false,"RutaArchivo es obligatoria.");var d=await _repo.RegistrarAdjuntoFlotaAsync(Empresa,Est,u,x,ct);return R(d,d.Ok,d.Mensaje);}
