 public async Task<JsonResponseRequest<FlotaUsuarioMobileSesionDto>> LoginMobileAsync(FlotaMobileLoginDto x,CancellationToken ct){x.Telefono=(x.Telefono??"").Trim();x.Pin=(x.Pin??"").Trim();if(string.IsNullOrWhiteSpace(x.Telefono))return R(new FlotaUsuarioMobileSesionDto(),false,"Ingresa el telefono.");if(string.IsNullOrWhiteSpace(x.Pin))return R(new FlotaUsuarioMobileSesionDto(),false,"Ingresa el PIN o contrasena temporal.");var user=await _repo.ObtenerUsuarioMobileLoginAsync(Empresa,Est,x.Telefono,ct);if(user==null)return R(new FlotaUsuarioMobileSesionDto(),false,"Telefono o PIN invalido.");if(!FlotaMobilePasswordHasher.Verify(x.Pin,user.PasswordHash,user.PasswordSalt))return R(new FlotaUsuarioMobileSesionDto(),false,"Telefono o PIN invalido.");return R(new FlotaUsuarioMobileSesionDto{IdUsuarioMobile=user.IdUsuarioMobile,IdChofer=user.IdChofer,IdContrato=user.IdContrato,Telefono=user.Telefono,Nombre=user.Nombre});}
